INSERT INTO `services` (`id`, `user_id`, `title`, `image`, `short_description`, `long_description`, `price`, `status`, `created_at`, `updated_at`) VALUES
(1, NULL, 'TV Services', NULL, '<p>Professional TV installation, repair, and setup services at your doorstep.</p>', '<h3 data-start=\"589\" data-end=\"623\"><strong data-start=\"593\" data-end=\"621\">A. Installation Services</strong></h3><ul data-start=\"624\" data-end=\"1007\">\r\n<li data-start=\"624\" data-end=\"746\">\r\n<p data-start=\"626\" data-end=\"746\"><strong data-start=\"626\" data-end=\"656\">Wall Mounting for All TVs:</strong> Hum LED, LCD, Smart TV aur Plasma TVs ka professional wall mounting provide karte hain.</p>\r\n</li>\r\n<li data-start=\"747\" data-end=\"867\">\r\n<p data-start=\"749\" data-end=\"867\"><strong data-start=\"749\" data-end=\"766\">Safety First:</strong> Installation ke dauran proper safety standards follow kiye jaate hain taake aapka TV damage na ho.</p>\r\n</li>\r\n<li data-start=\"868\" data-end=\"1007\">\r\n<p data-start=\"870\" data-end=\"1007\"><strong data-start=\"870\" data-end=\"891\">Custom Solutions:</strong> Har wall alag hoti hai, isliye hum customized brackets aur fittings use karte hain jo aapke ghar ke liye best ho.</p>\r\n</li>\r\n</ul><h3 data-start=\"1009\" data-end=\"1042\"><strong data-start=\"1013\" data-end=\"1040\">B. Repair &amp; Maintenance</strong></h3><ul data-start=\"1043\" data-end=\"1420\">\r\n<li data-start=\"1043\" data-end=\"1181\">\r\n<p data-start=\"1045\" data-end=\"1181\"><strong data-start=\"1045\" data-end=\"1067\">Screen Issues Fix:</strong> Agar aapke TV ke screen par lines aa rahi hain, ya black/blank screen aa rahi hai, hum uska solution dete hain.</p>\r\n</li>\r\n<li data-start=\"1182\" data-end=\"1288\">\r\n<p data-start=\"1184\" data-end=\"1288\"><strong data-start=\"1184\" data-end=\"1203\">Sound Problems:</strong> TV ke speaker kaam na karna ya distorted sound ka issue bhi hum repair karte hain.</p>\r\n</li>\r\n<li data-start=\"1289\" data-end=\"1420\">\r\n<p data-start=\"1291\" data-end=\"1420\"><strong data-start=\"1291\" data-end=\"1323\">Hardware &amp; Software Repairs:</strong> Remote sensor, power issues, motherboard faults ya software update ki services available hain.</p>\r\n</li>\r\n</ul><h3 data-start=\"1422\" data-end=\"1449\"><strong data-start=\"1426\" data-end=\"1447\">C. Tuning &amp; Setup</strong></h3><ul data-start=\"1450\" data-end=\"1764\">\r\n<li data-start=\"1450\" data-end=\"1567\">\r\n<p data-start=\"1452\" data-end=\"1567\"><strong data-start=\"1452\" data-end=\"1471\">Channel Tuning:</strong> Hum aapke TV ke channels ko properly set karte hain taake aapko best signal aur clarity mile.</p>\r\n</li>\r\n<li data-start=\"1568\" data-end=\"1686\">\r\n<p data-start=\"1570\" data-end=\"1686\"><strong data-start=\"1570\" data-end=\"1588\">Smart TV Apps:</strong> Netflix, YouTube, Amazon Prime jaise apps ka installation aur setup bhi provide kiya jaata hai.</p>\r\n</li>\r\n<li data-start=\"1687\" data-end=\"1764\">\r\n<p data-start=\"1689\" data-end=\"1764\"><strong data-start=\"1689\" data-end=\"1709\">Network Support:</strong> Wi-Fi aur LAN connectivity setup me madad milti hai.</p>\r\n</li>\r\n</ul><h3 data-start=\"1766\" data-end=\"1793\"><strong data-start=\"1770\" data-end=\"1791\">D. Why Choose Us?</strong></h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1794\" data-end=\"2165\">\r\n<li data-start=\"1794\" data-end=\"1878\">\r\n<p data-start=\"1796\" data-end=\"1878\"><strong data-start=\"1796\" data-end=\"1822\">Certified Technicians:</strong> Hamare technicians professional aur experienced hain.</p>\r\n</li>\r\n<li data-start=\"1879\" data-end=\"1982\">\r\n<p data-start=\"1881\" data-end=\"1982\"><strong data-start=\"1881\" data-end=\"1902\">Same-Day Service:</strong> Hum turant service provide karte hain, taake aapka TV zyada der band na rahe.</p>\r\n</li>\r\n<li data-start=\"1983\" data-end=\"2072\">\r\n<p data-start=\"1985\" data-end=\"2072\"><strong data-start=\"1985\" data-end=\"2008\">Affordable Pricing:</strong> Sabhi services budget-friendly hain, koi hidden charges nahi.</p>\r\n</li>\r\n<li data-start=\"2073\" data-end=\"2165\">\r\n<p data-start=\"2075\" data-end=\"2165\"><strong data-start=\"2075\" data-end=\"2101\">24/7 Customer Support:</strong> Koi bhi problem aaye to humse kabhi bhi contact kar sakte ho.</p></li></ul>', '$499.00', 1, '2025-07-30 05:34:42', '2025-07-30 05:59:22'),
(2, NULL, 'Internet Service', NULL, '<p>High-speed and reliable internet services for homes and businesses.</p>', '<h3 data-start=\"554\" data-end=\"592\"><strong data-start=\"558\" data-end=\"590\">A. Internet Connection Types</strong></h3><ul data-start=\"593\" data-end=\"843\">\r\n<li data-start=\"593\" data-end=\"681\">\r\n<p data-start=\"595\" data-end=\"681\"><strong data-start=\"595\" data-end=\"620\">Fiber-Optic Internet:</strong> Ultra-fast speed with maximum reliability for heavy usage.</p>\r\n</li>\r\n<li data-start=\"682\" data-end=\"762\">\r\n<p data-start=\"684\" data-end=\"762\"><strong data-start=\"684\" data-end=\"714\">Broadband/DSL Connections:</strong> Affordable and stable connectivity for homes.</p>\r\n</li>\r\n<li data-start=\"763\" data-end=\"843\">\r\n<p data-start=\"765\" data-end=\"843\"><strong data-start=\"765\" data-end=\"787\">Wireless Internet:</strong> 4G/5G &amp; Wi-Fi solutions for portable and rural areas.</p>\r\n</li>\r\n</ul><h3 data-start=\"845\" data-end=\"878\"><strong data-start=\"849\" data-end=\"876\">B. Installation &amp; Setup</strong></h3><ul data-start=\"879\" data-end=\"1151\">\r\n<li data-start=\"879\" data-end=\"962\">\r\n<p data-start=\"881\" data-end=\"962\"><strong data-start=\"881\" data-end=\"907\">Same-Day Installation:</strong> Modem, router, and wiring setup done professionally.</p>\r\n</li>\r\n<li data-start=\"963\" data-end=\"1055\">\r\n<p data-start=\"965\" data-end=\"1055\"><strong data-start=\"965\" data-end=\"991\">Network Configuration:</strong> We set up your Wi-Fi, secure passwords, and optimize signals.</p>\r\n</li>\r\n<li data-start=\"1056\" data-end=\"1151\">\r\n<p data-start=\"1058\" data-end=\"1151\"><strong data-start=\"1058\" data-end=\"1082\">Device Connectivity:</strong> Help in connecting smart TVs, laptops, mobiles, and other devices.</p>\r\n</li>\r\n</ul><h3 data-start=\"1153\" data-end=\"1187\"><strong data-start=\"1157\" data-end=\"1185\">C. Maintenance &amp; Support</strong></h3><ul data-start=\"1188\" data-end=\"1460\">\r\n<li data-start=\"1188\" data-end=\"1286\">\r\n<p data-start=\"1190\" data-end=\"1286\"><strong data-start=\"1190\" data-end=\"1217\">Troubleshooting Issues:</strong> Slow speed, connectivity drops, or complete outages fixed quickly.</p>\r\n</li>\r\n<li data-start=\"1287\" data-end=\"1377\">\r\n<p data-start=\"1289\" data-end=\"1377\"><strong data-start=\"1289\" data-end=\"1312\">Upgrades &amp; Add-ons:</strong> Plan upgrades, new routers, and mesh network setups available.</p>\r\n</li>\r\n<li data-start=\"1378\" data-end=\"1460\">\r\n<p data-start=\"1380\" data-end=\"1460\"><strong data-start=\"1380\" data-end=\"1407\">24/7 Technical Support:</strong> Always available to assist with internet problems.</p>\r\n</li>\r\n</ul><h3 data-start=\"1462\" data-end=\"1507\"><strong data-start=\"1466\" data-end=\"1505\">D. Why Choose Our Internet Service?</strong></h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1508\" data-end=\"1828\">\r\n<li data-start=\"1508\" data-end=\"1591\">\r\n<p data-start=\"1510\" data-end=\"1591\"><strong data-start=\"1510\" data-end=\"1538\">High-Speed Connectivity:</strong> Perfect for streaming, gaming, and work-from-home.</p>\r\n</li>\r\n<li data-start=\"1592\" data-end=\"1661\">\r\n<p data-start=\"1594\" data-end=\"1661\"><strong data-start=\"1594\" data-end=\"1614\">Reliable Uptime:</strong> Minimum downtime with robust infrastructure.</p>\r\n</li>\r\n<li data-start=\"1662\" data-end=\"1747\">\r\n<p data-start=\"1664\" data-end=\"1747\"><strong data-start=\"1664\" data-end=\"1686\">Flexible Packages:</strong> Multiple packages as per your data and speed requirements.</p>\r\n</li>\r\n<li data-start=\"1748\" data-end=\"1828\">\r\n<p data-start=\"1750\" data-end=\"1828\"><strong data-start=\"1750\" data-end=\"1779\">Customer-Centric Service:</strong> Affordable rates with dedicated customer care.</p></li></ul>', '$449.00', 1, '2025-07-30 05:35:59', '2025-07-30 05:58:58'),
(3, NULL, 'Home Phone Service', NULL, '<p>Reliable and affordable home phone services with clear voice quality.</p>', '<h3 data-start=\"541\" data-end=\"569\"><strong data-start=\"545\" data-end=\"567\">A. Service Options</strong></h3><ul data-start=\"570\" data-end=\"805\">\r\n<li data-start=\"570\" data-end=\"637\">\r\n<p data-start=\"572\" data-end=\"637\"><strong data-start=\"572\" data-end=\"597\">Traditional Landline:</strong> Stable and crystal-clear connections.</p>\r\n</li>\r\n<li data-start=\"638\" data-end=\"720\">\r\n<p data-start=\"640\" data-end=\"720\"><strong data-start=\"640\" data-end=\"660\">VoIP Home Phone:</strong> Internet-based home phone service with advanced features.</p>\r\n</li>\r\n<li data-start=\"721\" data-end=\"805\">\r\n<p data-start=\"723\" data-end=\"805\"><strong data-start=\"723\" data-end=\"751\">Unlimited Calling Plans:</strong> Affordable plans for local and long-distance calls.</p>\r\n</li>\r\n</ul><h3 data-start=\"807\" data-end=\"840\"><strong data-start=\"811\" data-end=\"838\">B. Installation &amp; Setup</strong></h3><ul data-start=\"841\" data-end=\"1107\">\r\n<li data-start=\"841\" data-end=\"928\">\r\n<p data-start=\"843\" data-end=\"928\"><strong data-start=\"843\" data-end=\"866\">Quick Installation:</strong> Wiring and device setup completed by certified technicians.</p>\r\n</li>\r\n<li data-start=\"929\" data-end=\"1032\">\r\n<p data-start=\"931\" data-end=\"1032\"><strong data-start=\"931\" data-end=\"960\">Home Network Integration:</strong> Phone line properly configured with existing internet or cable setup.</p>\r\n</li>\r\n<li data-start=\"1033\" data-end=\"1107\">\r\n<p data-start=\"1035\" data-end=\"1107\"><strong data-start=\"1035\" data-end=\"1057\">Multiple Handsets:</strong> Support for connecting multiple phones at home.</p>\r\n</li>\r\n</ul><h3 data-start=\"1109\" data-end=\"1141\"><strong data-start=\"1113\" data-end=\"1139\">C. Features &amp; Benefits</strong></h3><ul data-start=\"1142\" data-end=\"1429\">\r\n<li data-start=\"1142\" data-end=\"1212\">\r\n<p data-start=\"1144\" data-end=\"1212\"><strong data-start=\"1144\" data-end=\"1167\">Voicemail Services:</strong> Easy-to-access voicemail for missed calls.</p>\r\n</li>\r\n<li data-start=\"1213\" data-end=\"1280\">\r\n<p data-start=\"1215\" data-end=\"1280\"><strong data-start=\"1215\" data-end=\"1244\">Caller ID &amp; Call Waiting:</strong> Stay informed about your callers.</p>\r\n</li>\r\n<li data-start=\"1281\" data-end=\"1356\">\r\n<p data-start=\"1283\" data-end=\"1356\"><strong data-start=\"1283\" data-end=\"1309\">International Calling:</strong> Competitive rates for international numbers.</p>\r\n</li>\r\n<li data-start=\"1357\" data-end=\"1429\">\r\n<p data-start=\"1359\" data-end=\"1429\"><strong data-start=\"1359\" data-end=\"1385\">Emergency 911 Support:</strong> Reliable emergency services availability.</p>\r\n</li>\r\n</ul><h3 data-start=\"1431\" data-end=\"1478\"><strong data-start=\"1435\" data-end=\"1476\">D. Why Choose Our Home Phone Service?</strong></h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1479\" data-end=\"1761\">\r\n<li data-start=\"1479\" data-end=\"1545\">\r\n<p data-start=\"1481\" data-end=\"1545\"><strong data-start=\"1481\" data-end=\"1505\">Clear Voice Quality:</strong> No call drops or static interference.</p>\r\n</li>\r\n<li data-start=\"1546\" data-end=\"1620\">\r\n<p data-start=\"1548\" data-end=\"1620\"><strong data-start=\"1548\" data-end=\"1577\">Budget-Friendly Packages:</strong> Plans for every household size and need.</p>\r\n</li>\r\n<li data-start=\"1621\" data-end=\"1682\">\r\n<p data-start=\"1623\" data-end=\"1682\"><strong data-start=\"1623\" data-end=\"1649\">24/7 Customer Support:</strong> Assistance available any time.</p>\r\n</li>\r\n<li data-start=\"1683\" data-end=\"1761\">\r\n<p data-start=\"1685\" data-end=\"1761\"><strong data-start=\"1685\" data-end=\"1704\">Bundle Options:</strong> Discounts when combined with Internet and TV Services.</p></li></ul>', '$399.00', 1, '2025-07-30 05:48:45', '2025-07-30 05:58:37'),
(4, NULL, 'Mobile Plans', NULL, '<p>Affordable mobile plans with nationwide coverage and unlimited options.</p>', '<h3 data-start=\"529\" data-end=\"554\"><strong data-start=\"533\" data-end=\"552\">A. Plan Options</strong></h3><ul data-start=\"555\" data-end=\"829\">\r\n<li data-start=\"555\" data-end=\"618\">\r\n<p data-start=\"557\" data-end=\"618\"><strong data-start=\"557\" data-end=\"575\">Prepaid Plans:</strong> Pay-as-you-go packages with flexibility.</p>\r\n</li>\r\n<li data-start=\"619\" data-end=\"683\">\r\n<p data-start=\"621\" data-end=\"683\"><strong data-start=\"621\" data-end=\"640\">Postpaid Plans:</strong> Monthly billing with exclusive benefits.</p>\r\n</li>\r\n<li data-start=\"684\" data-end=\"747\">\r\n<p data-start=\"686\" data-end=\"747\"><strong data-start=\"686\" data-end=\"711\">Unlimited Data Plans:</strong> Perfect for heavy internet users.</p>\r\n</li>\r\n<li data-start=\"748\" data-end=\"829\">\r\n<p data-start=\"750\" data-end=\"829\"><strong data-start=\"750\" data-end=\"775\">Family &amp; Group Plans:</strong> Share data, minutes, and texts with multiple lines.</p>\r\n</li>\r\n</ul><h3 data-start=\"831\" data-end=\"861\"><strong data-start=\"835\" data-end=\"859\">B. Features Included</strong></h3><ul data-start=\"862\" data-end=\"1148\">\r\n<li data-start=\"862\" data-end=\"940\">\r\n<p data-start=\"864\" data-end=\"940\"><strong data-start=\"864\" data-end=\"892\">Unlimited Calls &amp; Texts:</strong> Stay connected without worrying about limits.</p>\r\n</li>\r\n<li data-start=\"941\" data-end=\"1016\">\r\n<p data-start=\"943\" data-end=\"1016\"><strong data-start=\"943\" data-end=\"963\">High-Speed Data:</strong> 4G/5G coverage with maximum speed and reliability.</p>\r\n</li>\r\n<li data-start=\"1017\" data-end=\"1083\">\r\n<p data-start=\"1019\" data-end=\"1083\"><strong data-start=\"1019\" data-end=\"1045\">International Roaming:</strong> Affordable rates for travel abroad.</p>\r\n</li>\r\n<li data-start=\"1084\" data-end=\"1148\">\r\n<p data-start=\"1086\" data-end=\"1148\"><strong data-start=\"1086\" data-end=\"1106\">Hotspot Sharing:</strong> Use your data to connect other devices.</p>\r\n</li>\r\n</ul><h3 data-start=\"1150\" data-end=\"1177\"><strong data-start=\"1154\" data-end=\"1175\">C. Device Options</strong></h3><ul data-start=\"1178\" data-end=\"1417\">\r\n<li data-start=\"1178\" data-end=\"1255\">\r\n<p data-start=\"1180\" data-end=\"1255\"><strong data-start=\"1180\" data-end=\"1213\">Bring Your Own Device (BYOD):</strong> Use your existing phone with our plans.</p>\r\n</li>\r\n<li data-start=\"1256\" data-end=\"1338\">\r\n<p data-start=\"1258\" data-end=\"1338\"><strong data-start=\"1258\" data-end=\"1281\">Latest Smartphones:</strong> Get the newest devices with easy monthly installments.</p>\r\n</li>\r\n<li data-start=\"1339\" data-end=\"1417\">\r\n<p data-start=\"1341\" data-end=\"1417\"><strong data-start=\"1341\" data-end=\"1369\">Device Protection Plans:</strong> Insurance against accidental damage or theft.</p>\r\n</li>\r\n</ul><h3 data-start=\"1419\" data-end=\"1460\"><strong data-start=\"1423\" data-end=\"1458\">D. Why Choose Our Mobile Plans?</strong></h3><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul data-start=\"1461\" data-end=\"1712\">\r\n<li data-start=\"1461\" data-end=\"1530\">\r\n<p data-start=\"1463\" data-end=\"1530\"><strong data-start=\"1463\" data-end=\"1487\">Nationwide Coverage:</strong> Strong signals in urban and rural areas.</p>\r\n</li>\r\n<li data-start=\"1531\" data-end=\"1585\">\r\n<p data-start=\"1533\" data-end=\"1585\"><strong data-start=\"1533\" data-end=\"1556\">Affordable Pricing:</strong> Packages for every budget.</p>\r\n</li>\r\n<li data-start=\"1586\" data-end=\"1648\">\r\n<p data-start=\"1588\" data-end=\"1648\"><strong data-start=\"1588\" data-end=\"1611\">Flexible Contracts:</strong> No hidden fees or strict lock-ins.</p>\r\n</li>\r\n<li data-start=\"1649\" data-end=\"1712\">\r\n<p data-start=\"1651\" data-end=\"1712\"><strong data-start=\