(8, NULL, 'Customer Support', NULL, '<p>24/7 customer support to assist you with all your service needs.</p>', '<h3 data-start=\"523\" data-end=\"552\"><strong data-start=\"527\" data-end=\"550\">A. Support Channels</strong></h3><ul data-start=\"553\" data-end=\"840\">\r\n<li data-start=\"553\" data-end=\"623\">\r\n<p data-start=\"555\" data-end=\"623\"><strong data-start=\"555\" data-end=\"573\">Phone Support:</strong> Direct helpline for all queries and complaints.</p>\r\n</li>\r\n<li data-start=\"624\" data-end=\"693\">\r\n<p data-start=\"626\" data-end=\"693\"><strong data-start=\"626\" data-end=\"644\">Email Support:</strong> Fast responses to service requests and issues.</p>\r\n</li>\r\n<li data-start=\"694\" data-end=\"761\">\r\n<p data-start=\"696\" data-end=\"761\"><strong data-start=\"696\" data-end=\"710\">Live Chat:</strong> Instant help through website or app chat option.</p>\r\n</li>\r\n<li data-start=\"762\" data-end=\"840\">\r\n<p data-start=\"764\" data-end=\"840\"><strong data-start=\"764\" data-end=\"789\">Social Media Support:</strong> Assistance via Facebook, Twitter, WhatsApp, etc.</p>\r\n</li>\r\n</ul><h3 data-start=\"842\" data-end=\"883\"><strong data-start=\"846\" data-end=\"881\">B. Types of Assistance Provided</strong></h3><ul data-start=\"884\" data-end=\"1210\">\r\n<li data-start=\"884\" data-end=\"960\">\r\n<p data-start=\"886\" data-end=\"960\"><strong data-start=\"886\" data-end=\"909\">Billing &amp; Payments:</strong> Help with invoices, payments, and plan upgrades.</p>\r\n</li>\r\n<li data-start=\"961\" data-end=\"1043\">\r\n<p data-start=\"963\" data-end=\"1043\"><strong data-start=\"963\" data-end=\"985\">Technical Support:</strong> Fix issues related to TV, Internet, and Phone services.</p>\r\n</li>\r\n<li data-start=\"1044\" data-end=\"1127\">\r\n<p data-start=\"1046\" data-end=\"1127\"><strong data-start=\"1046\" data-end=\"1080\">Service Installation Guidance:</strong> Walkthroughs for new connections or devices.</p>\r\n</li>